 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Why does the preanalytical phase matter?",
   "back": "It includes every step before the analysis, often outside the lab, and 68 percent of errors in results come from it, causing extra costs and risks for patients."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Name the three phases of analysis.",
   "back": "Preanalytical: steps before the assay. Analytical: the dosage, the heart of the biologist's job, governed by the mandatory GBEA. Postanalytical: results and interpretation."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Name the preanalytical stakeholders.",
   "back": "The prescription (doctor), patient preparation, the equipment and the sampling procedure (nurse), and the sample itself (transport and storage)."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "What clinical information should the prescription give?",
   "back": "Time of sampling (cortisol, thyroid hormones, adrenaline vary daily), sex (testosterone), age (ALP higher in children from bone growth) and pregnancy (ALP up; proteins, iron and ferritin down)."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "How is blood drawn in a patient on an infusion?",
   "back": "Not from the infused vein; use the opposite arm. Otherwise wait 2 minutes after stopping, sample below the site, discard a first tube, and state the infusion and its type on the request."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What patient precautions are needed?",
   "back": "Rest 15 minutes in the same position (posture changes proteins and calcium); 12 hours of rest after exercise (CK can quadruple); fast at least 8 hours and sample at 7 to 9 a.m. (lipids can rise 21 percent, serum turns opalescent); avoid stress (prolactin, adrenaline, cortisol)."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "What must sampling equipment meet?",
   "back": "A conformity marking (CE or FDA), the standard EN/MN 14820 for single-use equipment, and the conditions of use on the leaflet, such as the expiry date."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "How should the tourniquet be used?",
   "back": "Only if needed: 7 to 10 cm above the site, not too tight, released within 1 minute; unnecessary if veins are visible or palpable. Poor use raises values up to 10 percent. Avoid it for lactate, ammonium, albumin and calcium."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Give the tube rules.",
   "back": "Respect the order of tubes to avoid additive carry-over; never transfer blood; respect filling volume (citrate 1:4); mix gently 5 to 10 times within 2 minutes. Separator gel tubes isolate serum or plasma from cells, stopping glucose use and potassium leak, and protect during transport."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "What is the compliance check?",
   "back": "Label tubes immediately after sampling with identity and number, and check the sample matches the request. Identity errors lead to rejection. Non-conformities cost about 25 percent of the sampling budget and must be managed under the GBEA and ISO 15189."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "Describe transport and storage.",
   "back": "Upright tubes; analyse within 2 hours, otherwise glucose falls and potassium and transaminases rise. Store at 4 to 8°C if delayed. Protect bilirubin samples from light."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Describe haemolysis and its consequences.",
   "back": "Causes: tight or long tourniquet, syringe turbulence (prefer vacuum), agitation, anaemia, stress, poor veins, long transport. Consequences: false potassium and enzyme results, repeat sampling, delayed care, unnecessary tests, slower lab work."
  }
 ],
 "deeper": [
  {
   "title": "Why a potassium of 6.5 might be a lab artefact",
   "html": "<p>Red cells hold most of the body's potassium. If a sample is haemolysed by a tight tourniquet or a small needle, or sits for hours before analysis, potassium leaks out and the result looks dangerously high. Before treating hyperkalaemia in a well patient, check whether the sample was haemolysed or delayed.</p><p class='src'>Source: the lecture's haemolysis and storage slides.</p>"
  }
 ],
