 "group": "Basics and hormones",
 "title": "Insulin",
 "sourceFile": "4 Insulin.pdf (Clinical Biochemistry, Prof. Nabiha Kamal)",
 "sourceUrl": "https://drive.google.com/file/d/1OAuXwHKvFXa-wnVSKvc9mMwero46oTYs/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Insulin is the body's only glucose-lowering hormone. It is released when glucose enters the beta cell and sets off a <strong>ATP → K+ channel closure → Ca2+ entry</strong> chain, and it tells liver, muscle and fat to <strong>store</strong> fuel.</p>"
  },
  {
   "id": "s1",
   "title": "Structure and synthesis",
   "html": "<p>A chain <strong>21</strong>, B chain <strong>30</strong> amino acids, three disulphide bridges; gene on <strong>chromosome 11</strong>. Preproinsulin → proinsulin → insulin + <strong>C-peptide</strong>.</p>"
  },
  {
   "id": "s2",
   "title": "Secretion",
   "html": "<p>Glucose → ATP up → <strong>K+ channels close</strong> → depolarisation → <strong>voltage-gated Ca2+ channels open</strong> → exocytosis. Insulin then activates its own gene to refill stores.</p>"
  },
  {
   "id": "s3",
   "title": "Actions",
   "html": "<p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Metabolism</th><th scope='col'>Activates</th><th scope='col'>Inhibits</th></tr></thead><tbody><tr><th scope='row'>Carbohydrate</th><td>Glycogenesis, glycolysis, pentose pathway</td><td>Gluconeogenesis, glycogenolysis, glucose release</td></tr><tr><th scope='row'>Lipid</th><td>Triglyceride synthesis, fatty acid uptake</td><td>Lipolysis</td></tr><tr><th scope='row'>Protein</th><td>Amino acid uptake, anabolism</td><td>Catabolism</td></tr><tr><th scope='row'>Genes</th><td>Glucokinase, pyruvate kinase, fatty acid synthase</td><td>Gluconeogenic genes</td></tr></tbody></table></div></p>"
  },
  {
   "id": "s4",
   "title": "Diabetes testing",
   "html": "<p>Diagnosis: fasting glucose, <strong>HbA1c</strong>, urine glucose and ketones, <strong>OGTT</strong> for prediabetes. Monitoring: glucose monthly, HbA1c every <strong>2 to 3 months</strong>, <strong>fructosamine</strong> (15 days) if haemoglobinopathy, lipids, microalbuminuria, creatinine.</p>"
  }
 ],
