 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "What is insulin and what does it do?",
   "back": "A peptide hormone from the beta cells of the islets of Langerhans, the only hypoglycaemic hormone, regulating glucose, fatty acids and ketone bodies. Secreted according to nutrition and activity; glucose is stored in muscle, fat and liver. It also affects growth; its absence is fatal within months."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Describe insulin structure and synthesis.",
   "back": "Two chains: A (21 amino acids) and B (30), with two interchain and one intrachain disulphide bridges. Gene on chromosome 11p. Preproinsulin becomes proinsulin (A-B-C), stored in granules; on stimulation a proteinase cleaves off the C-peptide, releasing insulin and C-peptide."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "How is insulin secretion triggered?",
   "back": "Glucose enters the beta cell and raises ATP, closing K+ channels; the membrane depolarises, opening voltage-gated calcium channels; calcium entry drives exocytosis. Released insulin acts back on its own receptor to activate its gene, restoring reserves."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Give insulin's carbohydrate effects.",
   "back": "Activates glycogenesis and glycolysis in liver and muscle, and the pentose phosphate pathway in liver. Inhibits gluconeogenesis, glycogenolysis and glucose release from the liver."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Give insulin's lipid, protein and sodium effects.",
   "back": "Lipid: fatty acid entry and triglyceride synthesis in adipocytes, glucose entry and conversion to acetyl-CoA; inhibits lipolysis. Protein: amino acid uptake and anabolism; inhibits catabolism and gluconeogenesis. Sodium: stimulates glucose-sodium cotransport."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "How does insulin modulate genes?",
   "back": "Activates lipogenesis (fatty acid synthetase) and glycolysis (glucokinase, pyruvate kinase); represses gluconeogenesis."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "How is diabetes diagnosed and monitored?",
   "back": "Diagnosis: fasting glucose, HbA1c (HPLC), glycosuria and ketonuria, oral glucose tolerance test for prediabetes. Monitoring: fasting and postprandial glucose monthly, HbA1c every 2 to 3 months, fructosamine every 15 days if haemoglobinopathy, urine strips, lipid profile, microalbuminuria, creatinine and urea."
  }
 ],
 "deeper": [
  {
   "title": "Why C-peptide tells you if insulin is the patient's own",
   "html": "<p>The beta cell releases insulin and C-peptide in equal amounts, but injected insulin contains no C-peptide. So a hypoglycaemic patient with high insulin but low C-peptide has been given insulin, while high levels of both point to the patient's own beta cells, as in an insulinoma.</p><p class='src'>Source: the lecture's proinsulin cleavage slide, with standard clinical reasoning.</p>"
  }
 ],
