 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Why explore the liver biochemically?",
   "back": "Blood tests are non-invasive compared with biopsy; they separate cellular from biliary damage, grade it, orient the diagnosis together, and are sensitive but not specific."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Give the liver's anatomy and blood supply.",
   "back": "1.5 kg, right subdiaphragmatic; about 1500 mL/min, 75 percent portal vein and 25 percent hepatic artery; drained by the hepatic veins to the IVC. Functional unit: the lobule. Bile flows from canaliculi to intrahepatic ducts, hepatic ducts, common hepatic duct, joined by the cystic duct as the common bile duct, meeting the pancreatic duct at the ampulla of Vater within the sphincter of Oddi."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "List the liver's functions.",
   "back": "Intermediate metabolism (carbohydrates, lipids, proteins, urea cycle), vitamins, iron storage as ferritin; synthesis of albumin, transport proteins and clotting factors; detoxification of drugs, alcohol and free bilirubin; synthesis and excretion of bile, its specific function (about 1 L/day)."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Describe bilirubin metabolism.",
   "back": "Free bilirubin from old red cells is toxic to the brain; the liver conjugates it with glucuronic acid. Conjugated bilirubin goes in bile to the gut, becomes stercobilinogen in stool; a little is reabsorbed into the enterohepatic cycle or excreted in urine as urobilinogen."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Describe bile.",
   "back": "Iso-osmotic, greenish yellow, pH 7.6 to 8.6; bile acids, bilirubin, cholesterol, phospholipids, water and electrolytes. It neutralises gastric acid with bicarbonate and forms micelles for fat digestion. Released when CCK contracts the gallbladder and the sphincter of Oddi opens."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Name the three liver syndromes and their markers.",
   "back": "Cytolysis: AST, ALT, LDH. Cholestasis: ALP, GGT, bilirubin. Hepatocellular insufficiency: ammonium, albumin, clotting factors. Specific markers: alpha-fetoprotein, alpha1-antitrypsin, ceruloplasmin."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Describe the transaminases.",
   "back": "ALT is more liver-specific; AST is also in heart and muscle. Avoid haemolysis (red cells hold 20 times more AST). Normal under 45 IU/L men, 35 women. Exercise, age and weight raise AST; alcohol and some drugs raise both. Very high in acute hepatitis, moderate in chronic disease; AST alone rises in infarction and muscle damage."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Describe LDH.",
   "back": "A cytoplasmic enzyme in heart, red cells, kidney, muscle and liver, so not liver-specific. Five isoenzymes: LDH5 liver, LDH1 heart, LDH2 red cells. Adult range 190 to 430 IU/L."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Define cholestasis and its consequences.",
   "back": "Reduced or stopped bile flow into the gut, from extrahepatic (stones, bile duct or pancreatic head cancer) or intrahepatic (hepatitis, cirrhosis, metastases) causes. In the gut: steatorrhoea, ADEK malabsorption with bleeding, pale stools. In blood: bile acids (pruritus), conjugated bilirubin (jaundice), cholesterol (doubles), ALP and GGT."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Describe ALP.",
   "back": "A membrane enzyme mainly of liver and bone. Higher in children (bone up to 90 percent) and in pregnancy from week 20; higher in men. Raised in cholestasis, bone disease (fracture healing, osteitis) and some cancers."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "Describe GGT.",
   "back": "A membrane glycoprotein of hepatic origin, 100 times more concentrated in bile. Sample fasting, avoid haemolysis. Normal under 50 IU/L men, 30 women; 7 to 8 times higher in neonates. Isolated rise: chronic alcoholism; also phenobarbital, paracetamol. Most sensitive hepatobiliary indicator; rises with ALP in cholestasis; also in pancreatic disease, diabetes, heart and kidney failure."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Describe bilirubin testing.",
   "back": "Free (unconjugated, fat-soluble, neurotoxic), conjugated (direct) and total. Protect from light. Total 3.4 to 17.1 µmol/L, conjugated 0 to 3.4. Jaundice in the conjunctiva above 30, skin above 50 µmol/L. Conjugated jaundice: bile duct obstruction, hepatocyte canalicular dysfunction, cirrhosis, hepatitis, neoplasia, congenital. Neonatal conjugated jaundice is rare but severe: neonatal hepatitis, biliary atresia."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "Describe the hepatocellular insufficiency markers.",
   "back": "Ammonium: 98 percent as NH4+, from protein breakdown and gut bacteria, removed only by the liver via the urea cycle; normal 0.3 to 0.7 mg/L; high in severe liver failure or urea cycle defects. Albumin: made only by the liver, 35 to 50 g/L, oncotic pressure and transport. Clotting: prothrombin time lengthens in liver failure and cholestasis; 3 seconds longer means bleeding risk; factors II, V, VII, X, XI."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "Name the specific liver markers.",
   "back": "Alpha-fetoprotein: main fetal protein, rises in hepatocellular carcinoma; screen cirrhosis and chronic hepatitis. Alpha1-antitrypsin deficiency: hereditary, leads to cirrhosis. Ceruloplasmin: copper transport, acute phase protein; collapses in Wilson's disease and liver failure."
  }
 ],
 "deeper": [
  {
   "title": "Why the prothrombin time is the best quick test of liver function",
   "html": "<p>Clotting factors are made by the liver and several have half-lives of hours, so the prothrombin time lengthens within a day of acute liver failure, long before albumin (half-life about three weeks) falls. If giving vitamin K corrects it, the problem was cholestasis; if not, the liver itself is failing.</p><p class='src'>Source: the lecture's coagulation factor slides, with standard physiology.</p>"
  }
 ],
